// include common definitions (must define DATA_TYPE, NI, NJ, NK, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (polybench-style sizes for gemm)
#include "gemm.hpp"

using namespace Halide;

// Alias for the numeric type used in the computation (e.g., float, double)
using num_t = DATA_TYPE;

/**
 * Initialize matrices A, B, C and scalars alpha, beta.
 *
 * C is NI x NJ
 * A is NI x NK
 * B is NK x NJ
 *
 * In C, arrays are declared as:
 *   DATA_TYPE C[NI][NJ];
 *   DATA_TYPE A[NI][NK];
 *   DATA_TYPE B[NK][NJ];
 *
 * and accessed as C[i][j], A[i][k], B[k][j].
 *
 * In Halide, the first dimension is the fastest-varying (like C's column index),
 * so we map them as:
 *   C(j, i)  <->  C[i][j]
 *   A(k, i)  <->  A[i][k]
 *   B(j, k)  <->  B[k][j]
 */
static void init_array(int ni, int nj, int nk,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    // Initialize alpha and beta scalars
    *alpha = static_cast<num_t>(1.5);
    *beta  = static_cast<num_t>(1.2);

    // Halide Vars
    Var i("i"), j("j"), k("k");

    // Halide Funcs for initialization
    Func init_C("init_C"), init_A("init_A"), init_B("init_B");

    // C[i][j] = ((i*j+1) % ni) / ni;
    // Buffer C is shaped (nj, ni) and accessed as C(j, i)
    init_C(j, i) = cast<num_t>(((i * j + 1) % ni)) / Expr(ni);

    // A[i][j] = (i*(j+1) % nk) / nk;
    // Here j is the "k" (second index), so A is (nk, ni) and accessed as A(k, i)
    init_A(k, i) = cast<num_t>((i * (k + 1) % nk)) / Expr(nk);

    // B[i][j] = (i*(j+2) % nj) / nj;
    // Here i is the "k" index and j is "j", so B is (nj, nk) and accessed as B(j, k)
    init_B(j, k) = cast<num_t>((k * (j + 2) % nj)) / Expr(nj);

    // Realize into the provided Buffers
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from PolyBench / gemm.hpp)
    int ni = NI; // number of rows of A and C
    int nj = NJ; // number of columns of B and C
    int nk = NK; // number of columns of A / rows of B

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: NI x NJ  ->  C(j, i) with shape (nj, ni)
    //   A: NI x NK  ->  A(k, i) with shape (nk, ni)
    //   B: NK x NJ  ->  B(j, k) with shape (nj, nk)
    Halide::Buffer<num_t, 2> C(nj, ni);
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);

    // Initialize data
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // ImageParams to pass Buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Bind the Buffers to the ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Halide Vars corresponding to C indices:
    // i: row index  (0..ni-1)
    // j: column index (0..nj-1)
    Var i("i"), j("j");

    // Reduction domain for k (0..nk-1)
    RDom k(0, A.dim(0).extent(), "k");

    // GEMM pipeline:
    // Original C code:
    //   for (i = 0; i < ni; i++) {
    //     for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //     for (k = 0; k < nk; k++) {
    //       for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //   }
    //
    // We compute:
    //   C(i,j) = beta * C(i,j)
    //   C(i,j) += alpha * sum_k A(i,k) * B(k,j)
    //
    // Mapping to Halide coordinates:
    //   gemm(j, i) <-> C[i][j]
    Func gemm("gemm");

    // Initialization: C[i][j] *= beta;
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Accumulation: C[i][j] += alpha * A[i][k] * B[k][j];
    // A_param(k, i) <-> A[i][k]
    // B_param(j, k) <-> B[k][j]
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // Schedule:
    // We preserve an execution order similar to the original C:
    //
    // For the pure definition (initial scaling by beta), we simply keep
    // i outer, j inner (which is the default for dims (j, i)), but we
    // can make it explicit:
    gemm.reorder(j, i); // j innermost, i outermost

    // For the reduction update, we want loops: for i, then k, then j,
    // matching:
    //   for (i) { for (k) { for (j) { ... } } }
    gemm.update().reorder(j, k, i);

    // Compile the kernel to machine code (JIT)
    gemm.compile_jit();

    // Measure execution time
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print result matrix to stderr (for debugging / DCE prevention)
    // Enable by passing any extra command-line arg.
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
