    // A is Buffer(nk, ni), so indices are (j, i) or (k, i).
    // A[i][k] = (i*(k+1) % nk) / nk;
    init_A(k, i) = cast<num_t>((i * (k + 1)) % nk) / cast<int>(nk);

    // B[i][j] with i in [0, nk), j in [0, nj)
    // B is Buffer(nj, nk), so indices are (j, i) or (j, k).
    // B[k][j] = (k*(j+2) % nj) / nj;
    init_B(j, k) = cast<num_t>((k * (j + 2)) % nj) / cast<int>(nj);

