    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Reduction definition: accumulate alpha*A[i][k]*B[k][j] over k.
    // C[i][j] += alpha * A[i][k] * B[k][j];
    //
    // In buffers:
    //   A_param(k, i) corresponds to A[i][k].
    //   B_param(j, k) corresponds to B[k][j].
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // Schedule:
    // - For the pure definition, gemm(j, i) has default loop nest:
    //     for (i) for (j)
    //   which matches the original scaling loop order.
    //   We explicitly reorder(j, i) to make j the innermost loop; this
    //   matches the default but makes intent obvious.
    gemm.reorder(j, i);

    // - For the reduction update, we want:
    //     for (i) {
    //       for (k) {
    //         for (j) { ... }
    //       }
    //     }
    //   which is exactly the original C kernel loop order:
    //     for i
    //       for k
    //         for j
    gemm.update().reorder(j, k, i);

    // Bind input buffers to ImageParams.
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel.
    gemm.compile_jit();

    // Time the execution using std::chrono.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write results back into C.
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix C to stderr if a non-empty
    // program name is present (mirrors the example).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                // C is stored as C(j, i)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout with 6 decimal digits.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
