// Use the original PolyBench benchmark-specific header.
// It defines NI, NJ, NK, DATA_TYPE, DATA_PRINTF_MODIFIER, etc.
#include "gemm.h"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize the input matrices A, B, C and the scalars alpha, beta.
 *
 * Original C code (logical shapes):
 *   C[ni][nj], A[ni][nk], B[nk][nj]
 *
 * In Halide, the first dimension is the fastest-varying (like the C inner
 * loop index). The original kernel uses:
 *   for (i = 0; i < ni; i++)
 *     for (j = 0; j < nj; j++)  // j inner
 *       ...
 *
 * So we map:
 *   C(i,j) in C code  -> Buffer C(j, i) in Halide of shape (nj, ni)
 *   A(i,k)            -> Buffer A(k, i) of shape (nk, ni)
 *   B(k,j)            -> Buffer B(j, k) of shape (nj, nk)
 *
 * This matches the access patterns in the original loops.
 */
static void init_array(int ni, int nj, int nk,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    // Halide Vars for initialization
    Var i("i"), j("j"), k("k");

    // Define Halide Funcs to initialize A, B, C with exactly the same
    // formulas as in the original C code, but with (j,i)/(k,i)/(j,k)
    // argument orders to match the Buffer shapes.
    Func init_C("init_C"), init_A("init_A"), init_B("init_B");

    // C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    //   i -> outer (rows), j -> inner (cols)
    //   C(j, i) in Halide
    init_C(j, i) = cast<num_t>((i * j + 1) % ni) / cast<int>(ni);

    // A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
    //   original indices: i (rows), j (cols) with j in [0, nk)
    //   we map A(k, i) where k is original j
    init_A(k, i) = cast<num_t>(i * (k + 1) % nk) / cast<int>(nk);

    // B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
    //   original indices: i in [0, nk), j in [0, nj)
    //   B(j, k) where k is original i
    init_B(j, k) = cast<num_t>(k * (j + 2) % nj) / cast<int>(nj);

    // Realize into the provided Buffers.
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from gemm.h / PolyBench)
    int ni = NI;
    int nj = NJ;
    int nk = NK;

    // Scalars
    num_t alpha;
    num_t beta;

    // Halide Buffers for matrices:
    //
    // Original shapes:
    //   C: [ni][nj]
    //   A: [ni][nk]
    //   B: [nk][nj]
    //
    // Halide shapes (fastest-varying dimension first):
    //   C(j,i) -> (nj, ni)
    //   A(k,i) -> (nk, ni)
    //   B(j,k) -> (nj, nk)
    Halide::Buffer<num_t, 2> C(nj, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> A(nk, ni);

    // Initialize data to match the C version.
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // ImageParams to represent input arrays to the Halide pipeline.
    // Dimensions are 2D with the same (x,y) ordering as the Buffers above.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Bind the ImageParams to the Buffers.
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars for the output indices; we follow the same (j,i) ordering as above:
    //   i: row index in [0, ni)
    //   j: column index in [0, nj)
    Var i("i"), j("j");

    // Reduction domain over k, corresponding to the original loop
    //   for (k = 0; k < nk; k++)
    RDom k(0, A.dim(0).extent(), "k");  // A.dim(0) == nk

    // Define the GEMM computation:
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_NI; i++) {
    //   for (j = 0; j < _PB_NJ; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_NK; k++) {
    //      for (j = 0; j < _PB_NJ; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // Mathematically:
    //   C[i][j] = beta * C[i][j] + alpha * sum_k A[i][k] * B[k][j];
    //
    // In Halide (with C(j,i), A(k,i), B(j,k)):
    Func gemm("gemm");

    // Pure definition: scale existing C by beta
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A(i,k) * B(k,j) over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // ------------------------------------------------------------------
    // Scheduling:
    //
    // We want the loop structure to reflect the original C code as closely
    // as possible:
    //
    // for i:
    //   for j:   (scale by beta)
    //   for k:
    //     for j: (accumulate over k)
    //
    // By default, a Func defined as gemm(j, i) would be computed with loops:
    //   for i:
    //     for j:
    //       ...
    //
    // For the update step, with RDom k, the default would be:
    //   for i:
    //     for j:
    //       for k:
    //         ...
    //
    // We reorder the update to:
    //   for i:
    //     for k:
    //       for j:
    //         ...
    //
    // which matches the original loop nest structure more closely.
    //
    // Note: reorder arguments are listed from innermost to outermost.
    gemm.reorder(j, i);              // pure: innermost j, outer i (already true, but explicit)
    gemm.update().reorder(j, k, i);  // update: innermost j, then k, then i (outermost)

    // Compile the kernel to machine code once (JIT).
    gemm.compile_jit();

    // Time the execution of the kernel (including just the Halide realize).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write results back into C.
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting matrix to stderr if any command-line
    // argument is supplied (to avoid excessive output by default).
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
